import os

base = 'C:\\AI-BS'
large_files = []

for root, dirs, files in os.walk(base):
    # skip hidden git
    if '.git' in dirs:
        dirs.remove('.git')
    for f in files:
        try:
            fp = os.path.join(root, f)
            sz = os.path.getsize(fp)
            if sz > 200 * 1024 * 1024:  # > 200 MB
                large_files.append((fp, sz))
        except:
            pass

large_files.sort(key=lambda x: x[1], reverse=True)
print(f'Found {len(large_files)} files > 200 MB. Top 25:')
for fp, sz in large_files[:25]:
    rel = os.path.relpath(fp, base)
    print(f'{sz/(1024**3):6.2f} GB : {rel}')
